Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Scalar multiplier k: <output id="scalarKVal">1</output><input id="scalarKInput" type="range" min="-3" max="3" step="0.5" value="1" oninput="document.getElementById('scalarKVal').value=this.value;update_scalarK(+this.value)"></label>
<label><input id="layoutModeInput" type="checkbox" onchange="toggle_layoutMode(this.checked)"> Layout: Overlay from same tail</label>
<span id="demoNarration" style="margin:0;font-size:10px;max-width:180px">At k = 1, the scaled vector kv is exactly the original vector v: same length and same direction.</span>
<span><button onclick="prevStep()">◀</button> <span id="stepLabel">1 / 4</span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var W = 600, H = 450;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var base = { dx: 100, dy: -35 };
var currentK = 1;
var overlayMode = false;
var currentStep = 0;

var colors = {
  navy: '#174a85',
  orange: '#ff5a1f',
  teal: '#0a8f93',
  red: '#d63b3b',
  purple: '#7b2cbf',
  gray: '#b7bcc3',
  black: '#000000'
};

var steps = [
  {
    title: 'Start with the original vector',
    narration: 'At k = 1, the scaled vector kv is exactly the original vector v: same length and same direction.',
    state: { scalarK: 1, layoutMode: 'Stacked comparison' }
  },
  {
    title: 'Stretch and shrink with positive scalars',
    narration: 'Move k to 3 or 1/2. The arrow stays parallel and points the same way; only its length changes in proportion to k.',
    state: { scalarK: 3, layoutMode: 'Stacked comparison' }
  },
  {
    title: 'Collapse at zero',
    narration: 'At k = 0, the vector has zero length, so the arrow collapses to its starting point.',
    state: { scalarK: 0, layoutMode: 'Overlay from same tail' }
  },
  {
    title: 'Reverse with a negative scalar',
    narration: 'At k = -1, the arrow has the same length as v but points in the opposite direction, giving -v.',
    state: { scalarK: -1, layoutMode: 'Overlay from same tail' }
  }
];

function formatK(v) {
  return (Math.abs(v - Math.round(v)) < 0.001) ? String(Math.round(v)) : String(v);
}

function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

function addMathLabel(parent, txt, x, y, color, size) {
  var t = parent.text(txt)
    .move(x, y)
    .font({ family: 'Georgia, Times New Roman, serif', size: size || 22, style: 'italic', weight: 'bold' })
    .fill(color || '#111');
  t.attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 4,
    'stroke-linejoin': 'round'
  });
  return t;
}

function addReadout(parent, txt, x, y) {
  var t = parent.text(txt)
    .move(x, y)
    .font({ family: 'Arial, sans-serif', size: 16, weight: 'bold' })
    .fill('#222');
  t.attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 4,
    'stroke-linejoin': 'round'
  });
  return t;
}

function endpoint(tail, k) {
  return { x: tail.x + k * base.dx, y: tail.y + k * base.dy };
}

function drawArrow(parent, tail, head, color, width, opts) {
  opts = opts || {};
  var g = parent.group();
  var dx = head.x - tail.x, dy = head.y - tail.y;
  var len = Math.sqrt(dx * dx + dy * dy);
  var opacity = opts.opacity == null ? 1 : opts.opacity;
  var dotRadius = opts.dotRadius || 5;
  var headLen = opts.headLen || 18;
  var headWidth = opts.headWidth || 12;

  if (opts.tailDot) {
    g.circle(dotRadius * 2).center(tail.x, tail.y).fill(colors.black);
  }

  if (len < 2.5) {
    g.circle(16).center(tail.x, tail.y)
      .fill({ color: color, opacity: 0.18 })
      .stroke({ color: color, width: Math.max(2, width), opacity: 0.95 });
    g.circle(6).center(tail.x, tail.y).fill(color);
    return g;
  }

  var ux = dx / len, uy = dy / len;
  var px = -uy, py = ux;
  var usableHead = Math.min(headLen, len * 0.42);
  var baseX = head.x - ux * usableHead;
  var baseY = head.y - uy * usableHead;

  g.line(tail.x, tail.y, baseX, baseY)
    .stroke({ color: color, width: width, linecap: 'round', opacity: opacity });

  g.polygon([
    [head.x, head.y],
    [baseX + px * headWidth / 2, baseY + py * headWidth / 2],
    [baseX - px * headWidth / 2, baseY - py * headWidth / 2]
  ]).fill({ color: color, opacity: opacity });

  return g;
}

function makeInteractive(el, tooltip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tooltip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
}

function drawReferenceVector(parent, tail) {
  var h = endpoint(tail, 1);
  var g = parent.group();
  g.line(tail.x, tail.y, h.x, h.y)
    .stroke({ color: colors.gray, width: 3, opacity: 0.7, linecap: 'round', dasharray: '7,6' });
  var uLen = Math.sqrt(base.dx * base.dx + base.dy * base.dy);
  var ux = base.dx / uLen, uy = base.dy / uLen;
  var px = -uy, py = ux;
  var bX = h.x - ux * 13, bY = h.y - uy * 13;
  g.polygon([
    [h.x, h.y],
    [bX + px * 4.5, bY + py * 4.5],
    [bX - px * 4.5, bY - py * 4.5]
  ]).fill({ color: colors.gray, opacity: 0.7 });
  return g;
}

function addStaticStack(labels) {
  var topTail = { x: 50, y: 135 };
  var vTail = { x: 50, y: 210 };
  var halfTail = { x: 50, y: 285 };
  var negTail = { x: 150, y: 325 };

  var a3 = drawArrow(draw, topTail, endpoint(topTail, 3), colors.navy, 4, { tailDot: true, headLen: 20, headWidth: 13 });
  var av = drawArrow(draw, vTail, endpoint(vTail, 1), colors.orange, 4, { tailDot: true, headLen: 18, headWidth: 12 });
  var ah = drawArrow(draw, halfTail, endpoint(halfTail, 0.5), colors.teal, 4, { tailDot: true, headLen: 15, headWidth: 10 });
  var an = drawArrow(draw, negTail, endpoint(negTail, -1), colors.red, 4, { tailDot: true, headLen: 18, headWidth: 12 });

  makeInteractive(a3, '3v: three times the length of v, same direction.', 'Positive scalar: 3v', 'Multiplying by 3 stretches the vector to three times its original length. Because 3 is positive, the arrow keeps the same direction.');
  makeInteractive(av, 'v: the original vector, corresponding to k = 1.', 'Original vector v', 'The vector v is the reference length and direction. A scalar multiple kv is compared to this arrow.');
  makeInteractive(ah, '1/2 v: half as long as v, same direction.', 'Positive scalar: 1/2 v', 'Multiplying by 1/2 shrinks the vector to half its length. Because the scalar is positive, the direction does not reverse.');
  makeInteractive(an, '-v: same length as v, opposite direction.', 'Negative scalar: -v', 'Multiplying by -1 keeps the length of v but reverses its direction. The tail dot is on the right because the arrow now points down-left.');

  addMathLabel(labels, '3v', 340, 6, '#111', 22);
  addMathLabel(labels, 'v', 158, 153, '#111', 22);
  addMathLabel(labels, '½v', 107, 246, '#111', 22);
  addMathLabel(labels, '−v', 160, 317, '#111', 22);
}

function addDynamicStack(labels) {
  var tail = { x: 300, y: 340 };
  if (Math.abs(currentK - 1) > 0.001) {
    drawReferenceVector(draw, tail);
  }

  var head = endpoint(tail, currentK);
  var dyn = drawArrow(draw, tail, head, colors.purple, 5, {
    tailDot: true,
    headLen: 20,
    headWidth: 14,
    dotRadius: 5
  });

  makeInteractive(
    dyn,
    'Dynamic vector kv: sign sets direction; |k| sets length.',
    'Dynamic scalar multiple kv',
    'Use the slider to change k. The arrow length is |k| times the length of v, and the arrow reverses when k is negative.'
  );

  var labelX, labelY;
  if (Math.abs(currentK) < 0.001) {
    labelX = tail.x + 12; labelY = tail.y - 30;
  } else {
    labelX = head.x + (currentK > 0 ? 8 : -44);
    labelY = head.y + (currentK > 0 ? -18 : 5);
  }
  addMathLabel(labels, 'kv', clamp(labelX, 12, 550), clamp(labelY, 8, 420), colors.purple, 22);
  addReadout(labels, 'k = ' + formatK(currentK), clamp(tail.x + 16, 10, 500), clamp(tail.y + 18, 10, 425));
}

function addOverlay(labels) {
  var tail = { x: 300, y: 250 };

  draw.line(15, tail.y - (15 - tail.x) * base.dy / base.dx, 585, tail.y + (585 - tail.x) * base.dy / base.dx)
    .stroke({ color: '#d9dde2', width: 2, dasharray: '7,7', linecap: 'round' });

  var a3 = drawArrow(draw, tail, endpoint(tail, 3), colors.navy, 4, { tailDot: false, opacity: 0.85, headLen: 19, headWidth: 12 });
  var av = drawArrow(draw, tail, endpoint(tail, 1), colors.orange, 4, { tailDot: false, opacity: 0.95, headLen: 18, headWidth: 12 });
  var ah = drawArrow(draw, tail, endpoint(tail, 0.5), colors.teal, 4, { tailDot: false, opacity: 0.95, headLen: 15, headWidth: 10 });
  var an = drawArrow(draw, tail, endpoint(tail, -1), colors.red, 4, { tailDot: false, opacity: 0.95, headLen: 18, headWidth: 12 });

  draw.circle(12).center(tail.x, tail.y).fill(colors.black);

  makeInteractive(a3, '3v extends farthest along the positive ray.', 'Overlay: positive multiples', 'In overlay mode, positive multiples of v all lie on the same ray from the shared tail. Larger positive scalars place the arrowhead farther along that ray.');
  makeInteractive(av, 'v is the one-unit reference vector.', 'Overlay: v', 'The original vector v marks the direction and one unit of vector length for the scalar multiple.');
  makeInteractive(ah, '1/2 v ends halfway to the tip of v.', 'Overlay: fractional multiple', 'A scalar between 0 and 1 shrinks the vector. The direction remains unchanged because the scalar is positive.');
  makeInteractive(an, '-v lies on the opposite ray.', 'Overlay: negative multiple', 'Negative multiples point along the opposite ray. The absolute value still controls the length.');

  addMathLabel(labels, '3v', 548, 116, '#111', 21);
  addMathLabel(labels, 'v', 407, 197, '#111', 21);
  addMathLabel(labels, '½v', 350, 221, '#111', 21);
  addMathLabel(labels, '−v', 174, 283, '#111', 21);

  var head = endpoint(tail, currentK);
  var dyn = drawArrow(draw, tail, head, colors.purple, 6, {
    tailDot: false,
    headLen: 21,
    headWidth: 15
  });

  if (Math.abs(currentK) < 0.001) {
    draw.circle(20).center(tail.x, tail.y)
      .fill({ color: colors.purple, opacity: 0.16 })
      .stroke({ color: colors.purple, width: 3 });
  }

  makeInteractive(
    dyn,
    'Current kv in purple.',
    'Current scalar multiple',
    'The purple arrow shows the value selected by the slider. Its length is multiplied by |k|, while its direction is determined by the sign of k.'
  );

  var lx, ly;
  if (Math.abs(currentK) < 0.001) {
    lx = tail.x + 16; ly = tail.y - 39;
  } else if (currentK > 0) {
    lx = head.x - 35; ly = head.y + 18;
  } else {
    lx = head.x + 10; ly = head.y - 12;
  }
  addMathLabel(labels, 'kv', clamp(lx, 12, 550), clamp(ly, 8, 420), colors.purple, 22);
  addReadout(labels, 'k = ' + formatK(currentK), 320, 300);
}

function renderScene() {
  draw.clear();
  draw.rect(W, H).fill('#ffffff');

  var labelLayer = draw.group();

  if (overlayMode) {
    addOverlay(labelLayer);
  } else {
    addStaticStack(labelLayer);
    addDynamicStack(labelLayer);
  }
}

function update_scalarK(v) {
  currentK = v;
  var out = document.getElementById('scalarKVal');
  if (out) out.value = formatK(v);
  renderScene();
}

function toggle_layoutMode(on) {
  overlayMode = !!on;
  renderScene();
}

function applyStep(i) {
  currentStep = (i + steps.length) % steps.length;
  var step = steps[currentStep];

  var k = step.state.scalarK;
