Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Scalar multiplier k: <output id="scalarKVal">1</output><input id="scalarKInput" type="range" min="-3" max="3" step="0.5" value="1" oninput="document.getElementById('scalarKVal').value=this.value;update_scalarK(+this.value)"></label>
<label><input id="layoutModeInput" type="checkbox" onchange="toggle_layoutMode(this.checked)"> Layout: Overlay from same tail</label>
<span id="demoNarration" style="margin:0;font-size:10px;max-width:180px">At k = 1, the scaled vector kv is exactly the original vector v: same length and same direction.</span>
<span><button onclick="prevStep()">◀</button> <span id="stepLabel">1 / 4</span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var W = 353, H = 361;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var colors = {
  navy: '#16477e',
  orange: '#ff5a1f',
  teal: '#0b8f92',
  red: '#d83b3f',
  purple: '#7b2cbf',
  gray: '#c9ced6',
  black: '#000000'
};

var sourceBase = { dx: 112, dy: -38 };
var currentK = 1;
var overlayMode = false;
var currentStep = 0;
var hasUserChangedSlider = false;

var steps = [
  {
    title: 'Start with the original vector',
    narration: 'At k = 1, the scaled vector kv is exactly the original vector v: same length and same direction.',
    state: { scalarK: 1, layoutMode: 'Stacked comparison' }
  },
  {
    title: 'Stretch and shrink with positive scalars',
    narration: 'Move k to 3 or 1/2. The arrow stays parallel and points the same way; only its length changes in proportion to k.',
    state: { scalarK: 3, layoutMode: 'Stacked comparison' }
  },
  {
    title: 'Collapse at zero',
    narration: 'At k = 0, the vector has zero length, so the arrow collapses to its starting point.',
    state: { scalarK: 0, layoutMode: 'Overlay from same tail' }
  },
  {
    title: 'Reverse with a negative scalar',
    narration: 'At k = -1, the arrow has the same length as v but points in the opposite direction, giving -v.',
    state: { scalarK: -1, layoutMode: 'Overlay from same tail' }
  }
];

function formatK(v) {
  if (Math.abs(v - Math.round(v)) < 0.001) return String(Math.round(v));
  return String(v).replace('-', '−');
}

function scalarLabel(v) {
  if (Math.abs(v - 1) < 0.001) return 'v';
  if (Math.abs(v - 3) < 0.001) return '3v';
  if (Math.abs(v - 0.5) < 0.001) return '1/2 v';
  if (Math.abs(v + 1) < 0.001) return '−v';
  if (Math.abs(v) < 0.001) return '0v';
  return formatK(v) + 'v';
}

function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

function endpoint(tail, k, base) {
  base = base || sourceBase;
  return { x: tail.x + k * base.dx, y: tail.y + k * base.dy };
}

function addMathLabel(parent, txt, x, y, color, size) {
  var t = parent.text(txt)
    .move(x, y)
    .font({ family: 'Georgia, Times New Roman, serif', size: size || 20, style: 'italic', weight: 'bold' })
    .fill(color || '#111');
  t.attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 3.5,
    'stroke-linejoin': 'round'
  });
  return t;
}

function addStackedHalfLabel(parent, x, y) {
  var g = parent.group();
  var one = g.text('1')
    .move(x + 1, y)
    .font({ family: 'Georgia, Times New Roman, serif', size: 14, weight: 'normal' })
    .fill('#111');
  var two = g.text('2')
    .move(x + 1, y + 16)
    .font({ family: 'Georgia, Times New Roman, serif', size: 14, weight: 'normal' })
    .fill('#111');
  g.line(x - 2, y + 16, x + 14, y + 16)
    .stroke({ color: '#111', width: 1.1, linecap: 'round' });
  var v = g.text('v')
    .move(x + 18, y + 13)
    .font({ family: 'Georgia, Times New Roman, serif', size: 19, style: 'italic', weight: 'bold' })
    .fill('#111');
  g.find('text').forEach(function (t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  });
  return g;
}

function addReadout(parent, txt, x, y) {
  var t = parent.text(txt)
    .move(x, y)
    .font({ family: 'Arial, sans-serif', size: 12, weight: 'bold' })
    .fill('#222');
  t.attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 3,
    'stroke-linejoin': 'round'
  });
  return t;
}

function drawArrow(parent, tail, head, color, width, opts) {
  opts = opts || {};
  var g = parent.group();
  var dx = head.x - tail.x, dy = head.y - tail.y;
  var len = Math.sqrt(dx * dx + dy * dy);
  var opacity = opts.opacity == null ? 1 : opts.opacity;
  var dotRadius = opts.dotRadius == null ? 4.4 : opts.dotRadius;
  var headLen = opts.headLen == null ? 16 : opts.headLen;
  var headWidth = opts.headWidth == null ? 10 : opts.headWidth;

  if (opts.tailDot) {
    g.circle(dotRadius * 2).center(tail.x, tail.y).fill(colors.black);
  }

  if (len < 2.2) {
    g.circle(15).center(tail.x, tail.y)
      .fill({ color: color, opacity: 0.16 })
      .stroke({ color: color, width: 2.2, opacity: 0.95 });
    g.circle(5.2).center(tail.x, tail.y).fill(color);
    return g;
  }

  var ux = dx / len, uy = dy / len;
  var px = -uy, py = ux;
  var usableHead = Math.min(headLen, len * 0.45);
  var baseX = head.x - ux * usableHead;
  var baseY = head.y - uy * usableHead;

  g.line(tail.x, tail.y, baseX, baseY)
    .stroke({ color: color, width: width, linecap: 'butt', opacity: opacity });

  g.polygon([
    [head.x, head.y],
    [baseX + px * headWidth / 2, baseY + py * headWidth / 2],
    [baseX - px * headWidth / 2, baseY - py * headWidth / 2]
  ]).fill({ color: color, opacity: opacity });

  return g;
}

function makeInteractive(el, tooltip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tooltip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
}

function addSubtleGlow(tail, head) {
  draw.line(tail.x, tail.y, head.x, head.y)
    .stroke({ color: colors.purple, width: 7, opacity: 0.18, linecap: 'round' })
    .back();
}

function drawReferenceVector(parent, tail, base) {
  var h = endpoint(tail, 1, base);
  var g = parent.group();
  g.line(tail.x, tail.y, h.x, h.y)
    .stroke({ color: colors.gray, width: 2, opacity: 0.78, linecap: 'round', dasharray: '5,5' });
  return g;
}

function addStaticStack(labelLayer) {
  var topTail = { x: 4, y: 135 };
  var vTail = { x: 4, y: 210 };
  var halfTail = { x: 4, y: 286 };
  var negTail = { x: 116, y: 323 };

  if (currentStep > 0 && !overlayMode) {
    if (Math.abs(currentK - 3) < 0.001) addSubtleGlow(topTail, endpoint(topTail, 3));
    if (Math.abs(currentK - 1) < 0.001) addSubtleGlow(vTail, endpoint(vTail, 1));
    if (Math.abs(currentK - 0.5) < 0.001) addSubtleGlow(halfTail, endpoint(halfTail, 0.5));
    if (Math.abs(currentK + 1) < 0.001) addSubtleGlow(negTail, endpoint(negTail, -1));
  }

  var a3 = drawArrow(draw, topTail, endpoint(topTail, 3), colors.navy, 3.2, { tailDot: true, headLen: 17, headWidth: 10 });
  var av = drawArrow(draw, vTail, endpoint(vTail, 1), colors.orange, 3.1, { tailDot: true, headLen: 15, headWidth: 9 });
  var ah = drawArrow(draw, halfTail, endpoint(halfTail, 0.5), colors.teal, 3.1, { tailDot: true, headLen: 13, headWidth: 8 });
  var an = drawArrow(draw, negTail, endpoint(negTail, -1), colors.red, 3.1, { tailDot: true, headLen: 15, headWidth: 9 });

  makeInteractive(a3, '3v: three times the length of v, same direction.', 'Positive scalar: 3v', 'Multiplying by 3 stretches the vector to three times its original length. Because 3 is positive, the arrow keeps the same direction.');
  makeInteractive(av, 'v: the original vector, corresponding to k = 1.', 'Original vector v', 'The vector v is the reference length and direction. A scalar multiple kv is compared to this arrow.');
  makeInteractive(ah, '1/2 v: half as long as v, same direction.', 'Positive scalar: 1/2 v', 'Multiplying by 1/2 shrinks the vector to half its length. Because the scalar is positive, the direction does not reverse.');
  makeInteractive(an, '-v: same length as v, opposite direction.', 'Negative scalar: -v', 'Multiplying by -1 keeps the length of v but reverses its direction. The tail dot is on the right because the arrow now points down-left.');

  addMathLabel(labelLayer, '3v', 329, -2, '#111', 20);
  addMathLabel(labelLayer, 'v', 111, 151, '#111', 20);
  addStackedHalfLabel(labelLayer, 54, 232);
  addMathLabel(labelLayer, '−v', 126, 317, '#111', 20);

  if (hasUserChangedSlider && currentStep === 0 && Math.abs(currentK - 1) > 0.001) {
    var dynTail = { x: 198, y: 318 };
    var dynBase = { dx: 44, dy: -15 };
    var head = endpoint(dynTail, currentK, dynBase);
    if (Math.abs(currentK - 1) > 0.001) drawReferenceVector(draw, dynTail, dynBase);
    var dyn = drawArrow(draw, dynTail, head, colors.purple, 3.5, { tailDot: true, headLen: 13, headWidth: 9 });
    makeInteractive(dyn, 'Current kv: |k| sets length; the sign sets direction.', 'Dynamic scalar multiple kv', 'Use the slider to change k. The arrow length is |k| times the reference length, and it reverses direction when k is negative.');
    addMathLabel(labelLayer, 'kv', clamp(head.x + (currentK >= 0 ? 5 : -29), 6, W - 34), clamp(head.y - 17, 8, H - 24), colors.purple, 17);
    addReadout(labelLayer, 'k = ' + formatK(currentK), 205, 333);
  }
}

function addOverlay(labelLayer) {
  var tail = { x: 178, y: 235 };
  var base = { dx: 50, dy: -17 };

  var lineLeftX = 12, lineRightX = 341;
  draw.line(
    lineLeftX,
    tail.y + (lineLeftX - tail.x) * base.dy / base.dx,
    lineRightX,
    tail.y + (lineRightX - tail.x) * base.dy / base.dx
  ).stroke({ color: '#d9dde2', width: 1.5, dasharray: '5,5', linecap: 'round' });

  var a3 = drawArrow(draw, tail, endpoint(tail, 3, base), colors.navy, 3.0, { tailDot: false, opacity: 0.84, headLen: 15, headWidth: 9 });
  var av = drawArrow(draw, tail, endpoint(tail, 1, base), colors.orange, 3.0, { tailDot: false, opacity: 0.95, headLen: 14, headWidth: 8.5 });
  var ah = drawArrow(draw, tail, endpoint(tail, 0.5, base), colors.teal, 3.0, { tailDot: false, opacity: 0.95, headLen: 11, headWidth: 7.5 });
  var an = drawArrow(draw, tail, endpoint(tail, -1, base), colors.red, 3.0, { tailDot: false, opacity: 0.95, headLen: 14, headWidth: 8.5 });

  draw.circle(9).center(tail.x, tail.y).fill(colors.black);

  makeInteractive(a3, '3v extends farthest along the positive ray.', 'Overlay: positive multiples', 'In overlay mode, positive multiples of v all lie on the same ray from the shared tail. Larger positive scalars place the arrowhead farther along that ray.');
  makeInteractive(av, 'v is the one-unit reference vector.', 'Overlay: v', 'The original vector v marks the direction and one unit of vector length for the scalar multiple.');
  makeInteractive(ah, '1/2 v ends halfway to the tip of v.', 'Overlay: fractional multiple', 'A scalar between 0 and 1 shrinks the vector. The direction remains unchanged because the scalar is positive.');
  makeInteractive(an, '-v lies on the opposite ray.', 'Overlay: negative multiple', 'Negative multiples point along the opposite ray. The absolute value still controls the length.');

  addMathLabel(labelLayer, '3v', 321, 171, '#111', 17);
  addMathLabel(labelLayer, 'v', 232, 208, '#111', 17);
  addStackedHalfLabel(labelLayer, 204, 217);
  addMathLabel(labelLayer, '−v', 118, 244, '#111', 17);

  if (Math.abs(currentK - 1) > 0.001) {
    drawReferenceVector(draw, tail, base);
  }

  var head = endpoint(tail, currentK, base);
  var dyn = drawArrow(draw, tail, head, colors.purple, 4.4, { tailDot: false, headLen: 16, headWidth: 10 });
  if (Math.abs(currentK) < 0.001) {
    draw.circle(18).center(tail.x, tail.y)
      .fill({ color: colors.purple, opacity: 0.15 })
      .stroke({ color: colors.purple, width: 2.4 });
  }

  makeInteractive(dyn, 'Current kv in purple: sign controls direction, |k| controls length.', 'Current scalar multiple', 'The purple arrow shows the value selected by the slider. Its length is multiplied by |k|, while its direction is determined by the sign of k.');

  var lx, ly;
  if (Math.abs(currentK) < 0.001) {
    lx = tail.x + 12; ly = tail.y - 33;
  } else if (currentK > 0) {
    lx = head.x + 6; ly = head.y - 20;
  } else {
    lx = head.x - 34; ly = head.y + 2;
  }
  addMathLabel(labelLayer, 'kv', clamp(lx, 6, W - 32), clamp(ly, 6, H - 24), colors.purple, 18);
  addReadout(labelLayer, 'k = ' + formatK(currentK), clamp(tail.x + 13, 8, W - 70), tail.y + 16);
}

function renderScene() {
  draw.clear();
  draw.rect(W, H).fill('#ffffff');
  var labelLayer = draw.group();

  if (overlayMode) {
    addOverlay(labelLayer);
  } else {
    addStaticStack(labelLayer);
  }
}

function update_scalarK(v) {
  hasUserChangedSlider = true;
  currentK = v;
  var out = document.getElementById('scalarKVal');
  if (out) out.value = formatK(v);
  renderScene();
}

function toggle_layoutMode(on) {
  overlayMode = !!on;
  if (overlayMode) hasUserChangedSlider = true;
  renderScene();
}

function applyStep(i) {
  currentStep = (i + steps.length) % steps.length;
  var step = steps[currentStep];

  currentK = step.state.scalarK;
  overlayMode = step.state.layoutMode === 'Overlay from same tail';
  hasUserChangedSlider = currentStep !== 0;

  var slider = document.getElementById('scalarKInput');
  var out = document.getElementById('scalarKVal');
  var check = document.getElementById('layoutModeInput');
  var narr = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');

  if (slider) slider.value = currentK;
  if (out) out.value = formatK(currentK);
  if (check) check.checked = overlayMode;
  if (narr) narr.textContent = step.narration;
  if (label) label.textContent = (currentStep + 1) + ' / ' + steps.length;

  renderScene();
}

function nextStep() {
  applyStep(currentStep + 1);
}

function prevStep() {
  applyStep(currentStep - 1);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
